css:
.loader {
  position: relative;
  width: 40px;
  height: 48px;
  border: 2px solid #c7d2fe;
  border-radius: 3px;
  box-sizing: border-box;
  overflow: hidden;
  background-image:
    repeating-linear-gradient(90deg, transparent 0 9px, rgba(99, 102, 241, 0.12) 9px 10px),
    repeating-linear-gradient(transparent 0 9px, rgba(99, 102, 241, 0.12) 9px 10px);
}
.loader::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 10px;
  background: #4338ca;
}
.loader i {
  position: absolute;
  left: 9px;
  width: 20px;
  height: 10px;
  background: #6366f1;
  border-radius: 2px;
  animation: fall 1.3s ease-in infinite;
}
.loader i::after {
  content: "";
  position: absolute;
  top: 10px;
  left: 5px;
  width: 10px;
  height: 10px;
  background: #6366f1;
  border-radius: 2px;
}
@keyframes fall {
  0% { top: -4px; opacity: 0; }
  15% { opacity: 1; }
  70% { top: 24px; }
  85% { top: 24px; opacity: 1; }
  100% { top: -4px; opacity: 0; }
}
